package com.geiq.plugin;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("geiq")
public interface GeIqConfig extends Config
{
	@ConfigItem(
		keyName = "syncCode",
		name = "Sync Code",
		description = "Your 6-character GE IQ sync code. Find it in the Sync menu on ge-iq.com",
		position = 1
	)
	default String syncCode()
	{
		return "";
	}

	@ConfigItem(
		keyName = "syncEnabled",
		name = "Enable Sync",
		description = "Toggle automatic trade syncing on/off",
		position = 2
	)
	default boolean syncEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "apiUrl",
		name = "API URL",
		description = "GE IQ API endpoint (don't change unless you know what you're doing)",
		position = 3
	)
	default String apiUrl()
	{
		return "https://ge-iq.com/api/trade";
	}
}

package com.geiq.plugin;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "GE IQ Sync",
	description = "Syncs Grand Exchange trades with GE IQ",
	tags = {"grand exchange", "flip", "trade", "sync"}
)
@Slf4j
public class GeIqPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "geiq";
	private static final String KEY_TOTAL_SYNCED = "totalSynced";
	private static final String KEY_LAST_SYNC_MS = "lastSyncMs";

	@Inject
	private Client client;

	@Inject
	private GeIqConfig config;

	@Inject
	private ApiClient apiClient;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	private final List<TradePayload> pendingTrades = new ArrayList<>();
	private ScheduledExecutorService executor;
	private NavigationButton navButton;
	private GeIqPluginPanel panel;
	private volatile SyncState syncState;
	private volatile long lastPullMs;

	@Override
	protected void startUp()
	{
		panel = new GeIqPluginPanel();
		refreshPanel();

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("GE IQ Sync")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		executor = Executors.newSingleThreadScheduledExecutor();
		executor.scheduleAtFixedRate(this::flushTrades, 5, 5, TimeUnit.SECONDS);
		executor.scheduleAtFixedRate(this::pollSyncState, 10, 60, TimeUnit.SECONDS);
		log.info("GE IQ Sync started");
	}

	@Override
	protected void shutDown()
	{
		flushTrades();
		if (executor != null)
		{
			executor.shutdown();
		}
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
		log.info("GE IQ Sync stopped");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CONFIG_GROUP.equals(event.getGroup()))
		{
			refreshPanel();
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (!config.syncEnabled())
		{
			return;
		}

		String syncCode = config.syncCode().trim().toUpperCase();
		if (syncCode.length() != 6)
		{
			return;
		}

		GrandExchangeOffer offer = event.getOffer();
		if (offer == null)
		{
			return;
		}

		GrandExchangeOfferState state = offer.getState();
		if (state == GrandExchangeOfferState.EMPTY)
		{
			return;
		}

		String status;
		switch (state)
		{
			case BUYING:
				status = "buying";
				break;
			case SELLING:
				status = "selling";
				break;
			case BOUGHT:
				status = "completed";
				break;
			case SOLD:
				status = "completed";
				break;
			case CANCELLED_BUY:
				status = "cancelled";
				break;
			case CANCELLED_SELL:
				status = "cancelled";
				break;
			default:
				return;
		}

		boolean isBuy = (state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY);

		int quantity = offer.getQuantitySold();
		int totalPrice = offer.getSpent();
		if (quantity <= 0)
		{
			return;
		}

		int itemId = offer.getItemId();
		String itemName = client.getItemDefinition(itemId).getName();

		TradePayload trade = new TradePayload(
			itemId, itemName, quantity, totalPrice,
			totalPrice / quantity, isBuy, status,
			event.getSlot(), System.currentTimeMillis()
		);

		synchronized (pendingTrades)
		{
			pendingTrades.add(trade);
		}

		log.debug("GE IQ: queued trade - {} {} x{} for {}gp",
			isBuy ? "BUY" : "SELL", itemName, quantity, totalPrice);
	}

	private void flushTrades()
	{
		List<TradePayload> toSend;
		synchronized (pendingTrades)
		{
			if (pendingTrades.isEmpty())
			{
				return;
			}
			toSend = new ArrayList<>(pendingTrades);
			pendingTrades.clear();
		}

		String syncCode = config.syncCode().trim().toUpperCase();
		if (syncCode.length() != 6)
		{
			return;
		}

		try
		{
			apiClient.sendTrades(config.apiUrl(), syncCode, toSend);
			int prevTotal = readInt(KEY_TOTAL_SYNCED, 0);
			long now = System.currentTimeMillis();
			configManager.setConfiguration(CONFIG_GROUP, KEY_TOTAL_SYNCED, prevTotal + toSend.size());
			configManager.setConfiguration(CONFIG_GROUP, KEY_LAST_SYNC_MS, now);
			refreshPanel();
			log.info("GE IQ: synced {} trades", toSend.size());
		}
		catch (Exception e)
		{
			log.warn("GE IQ: failed to sync trades", e);
			synchronized (pendingTrades)
			{
				pendingTrades.addAll(0, toSend);
				while (pendingTrades.size() > 100)
				{
					pendingTrades.remove(pendingTrades.size() - 1);
				}
			}
		}
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}
		int total = readInt(KEY_TOTAL_SYNCED, 0);
		long lastSync = readLong(KEY_LAST_SYNC_MS, 0L);
		panel.update(config.syncCode(), config.syncEnabled(), total, lastSync, syncState, lastPullMs);
	}

	private void pollSyncState()
	{
		if (!config.syncEnabled())
		{
			return;
		}
		String syncCode = config.syncCode().trim().toUpperCase();
		if (syncCode.length() != 6)
		{
			return;
		}
		try
		{
			SyncState state = apiClient.fetchSyncState(config.apiUrl(), syncCode);
			syncState = state;
			lastPullMs = System.currentTimeMillis();
			refreshPanel();
		}
		catch (Exception e)
		{
			log.debug("GE IQ: failed to pull sync state", e);
		}
	}

	private int readInt(String key, int fallback)
	{
		Integer v = configManager.getConfiguration(CONFIG_GROUP, key, Integer.class);
		return v == null ? fallback : v;
	}

	private long readLong(String key, long fallback)
	{
		Long v = configManager.getConfiguration(CONFIG_GROUP, key, Long.class);
		return v == null ? fallback : v;
	}

	@Provides
	GeIqConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GeIqConfig.class);
	}
}

package com.geiq.plugin;

public class TradePayload
{
	private final int itemId;
	private final String itemName;
	private final int quantity;
	private final int price;
	private final int pricePerItem;
	private final boolean isBuy;
	private final String status;
	private final int slot;
	private final long timestamp;

	public TradePayload(int itemId, String itemName, int quantity, int price,
						int pricePerItem, boolean isBuy, String status,
						int slot, long timestamp)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.quantity = quantity;
		this.price = price;
		this.pricePerItem = pricePerItem;
		this.isBuy = isBuy;
		this.status = status;
		this.slot = slot;
		this.timestamp = timestamp;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getItemName()
	{
		return itemName;
	}

	public int getQuantity()
	{
		return quantity;
	}

	public int getPrice()
	{
		return price;
	}

	public int getPricePerItem()
	{
		return pricePerItem;
	}

	public boolean isBuy()
	{
		return isBuy;
	}

	public String getStatus()
	{
		return status;
	}

	public int getSlot()
	{
		return slot;
	}

	public long getTimestamp()
	{
		return timestamp;
	}
}

package com.geiq.plugin;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

class GeIqPluginPanel extends PluginPanel
{
	private static final String GE_IQ_URL = "https://ge-iq.com";

	private final JLabel statusValue = new JLabel("Not configured");
	private final JLabel syncCodeValue = new JLabel("-");
	private final JLabel totalSyncedValue = new JLabel("0 trades");
	private final JLabel lastSyncValue = new JLabel("Never");

	private final JLabel watchingValue = new JLabel("—");
	private final JLabel activeFlipsValue = new JLabel("—");
	private final JLabel investmentsValue = new JLabel("—");
	private final JLabel pulledAtValue = new JLabel("Never");

	private long lastSyncMs = 0;
	private long lastPullMs = 0;

	GeIqPluginPanel()
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel title = new JLabel("GE IQ Sync");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(title);
		content.add(Box.createVerticalStrut(12));

		content.add(buildRow("Status", statusValue));
		content.add(Box.createVerticalStrut(10));
		content.add(buildRow("Sync code", syncCodeValue));
		content.add(Box.createVerticalStrut(10));
		content.add(buildRow("Total synced", totalSyncedValue));
		content.add(Box.createVerticalStrut(10));
		content.add(buildRow("Last sync", lastSyncValue));
		content.add(Box.createVerticalStrut(16));

		content.add(buildSectionHeader("From GE IQ"));
		content.add(Box.createVerticalStrut(8));
		content.add(buildRow("Watching", watchingValue));
		content.add(Box.createVerticalStrut(10));
		content.add(buildRow("Active flips", activeFlipsValue));
		content.add(Box.createVerticalStrut(10));
		content.add(buildRow("Investments", investmentsValue));
		content.add(Box.createVerticalStrut(10));
		content.add(buildRow("Pulled", pulledAtValue));
		content.add(Box.createVerticalStrut(18));

		JButton openButton = new JButton("Open GE IQ");
		openButton.setFocusPainted(false);
		openButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		openButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		openButton.addActionListener(e -> LinkBrowser.browse(GE_IQ_URL));
		content.add(openButton);

		add(content, BorderLayout.NORTH);

		Timer refreshTimer = new Timer(15000, e -> {
			updateLastSyncDisplay();
			updatePulledAtDisplay();
		});
		refreshTimer.start();
	}

	private JPanel buildSectionHeader(String label)
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel l = new JLabel(label);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.BRAND_ORANGE);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(l);
		return header;
	}

	private JPanel buildRow(String label, JLabel valueLabel)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel l = new JLabel(label);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);

		valueLabel.setFont(FontManager.getRunescapeFont());
		valueLabel.setForeground(ColorScheme.BRAND_ORANGE);
		valueLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		row.add(l);
		row.add(valueLabel);
		return row;
	}

	void update(String syncCode, boolean enabled, int totalSynced, long lastSync, SyncState state, long pulledAt)
	{
		this.lastSyncMs = lastSync;
		this.lastPullMs = pulledAt;
		SwingUtilities.invokeLater(() -> {
			String code = syncCode == null ? "" : syncCode.trim().toUpperCase();
			boolean configured = code.length() == 6;

			if (!configured)
			{
				statusValue.setText("Not configured");
				statusValue.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			}
			else if (!enabled)
			{
				statusValue.setText("Disabled");
				statusValue.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			}
			else
			{
				statusValue.setText("Connected");
				statusValue.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
			}

			syncCodeValue.setText(configured ? code : "-");
			totalSyncedValue.setText(totalSynced + (totalSynced == 1 ? " trade" : " trades"));

			if (state == null)
			{
				watchingValue.setText("—");
				activeFlipsValue.setText("—");
				investmentsValue.setText("—");
			}
			else
			{
				int watching = state.favoritesOrEmpty().size();
				long activeFlips = state.portfolioOrEmpty().stream()
					.filter(SyncState.PortfolioItem::isActive)
					.count();
				long investments = state.investmentsOrEmpty().stream()
					.filter(SyncState.Investment::isActive)
					.count();
				watchingValue.setText(watching + (watching == 1 ? " item" : " items"));
				activeFlipsValue.setText(String.valueOf(activeFlips));
				investmentsValue.setText(String.valueOf(investments));
			}

			updateLastSyncDisplay();
			updatePulledAtDisplay();
		});
	}

	private void updatePulledAtDisplay()
	{
		pulledAtValue.setText(lastPullMs <= 0 ? "Never" : agoString(System.currentTimeMillis() - lastPullMs));
	}

	private void updateLastSyncDisplay()
	{
		lastSyncValue.setText(lastSyncMs <= 0 ? "Never" : agoString(System.currentTimeMillis() - lastSyncMs));
	}

	private static String agoString(long diffMs)
	{
		long sec = diffMs / 1000;
		if (sec < 60) return sec + "s ago";
		if (sec < 3600) return (sec / 60) + "m ago";
		if (sec < 86400) return (sec / 3600) + "h ago";
		return (sec / 86400) + "d ago";
	}
}

package com.geiq.plugin;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Singleton
public class ApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	public ApiClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	public void sendTrades(String apiUrl, String syncCode, List<TradePayload> trades) throws IOException
	{
		JsonObject body = new JsonObject();
		body.addProperty("syncCode", syncCode);
		body.add("trades", gson.toJsonTree(trades));

		Request request = new Request.Builder()
			.url(apiUrl)
			.header("User-Agent", "GE IQ RuneLite Plugin")
			.header("Content-Type", "application/json")
			.post(RequestBody.create(JSON, body.toString()))
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				throw new IOException("GE IQ API returned " + response.code());
			}
		}
	}

	/**
	 * GET /api/sync-push?code={syncCode}. Returns null when the server has no synced
	 * data for this code (HTTP 404); throws on transport errors or other failures.
	 * Derives the URL from the trade URL by replacing the trailing path segment so
	 * /api/trade → /api/sync-push.
	 */
	public SyncState fetchSyncState(String apiUrl, String syncCode) throws IOException
	{
		String pullUrl = derivePullUrl(apiUrl) + "?code=" + URLEncoder.encode(syncCode, StandardCharsets.UTF_8.name());

		Request request = new Request.Builder()
			.url(pullUrl)
			.header("User-Agent", "GE IQ RuneLite Plugin")
			.get()
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (response.code() == 404)
			{
				return null;
			}
			if (!response.isSuccessful())
			{
				throw new IOException("GE IQ sync state fetch returned " + response.code());
			}
			ResponseBody body = response.body();
			if (body == null)
			{
				throw new IOException("GE IQ sync state fetch returned empty body");
			}
			return gson.fromJson(body.charStream(), SyncState.class);
		}
	}

	/**
	 * Replace the last path segment of the trade URL with "sync-push".
	 * Example: https://ge-iq.com/api/trade → https://ge-iq.com/api/sync-push
	 */
	static String derivePullUrl(String apiUrl)
	{
		String trimmed = apiUrl;
		while (trimmed.endsWith("/"))
		{
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		}
		int queryIdx = trimmed.indexOf('?');
		String base = queryIdx >= 0 ? trimmed.substring(0, queryIdx) : trimmed;
		int lastSlash = base.lastIndexOf('/');
		// Don't slice off the scheme's "//"
		if (lastSlash > "https://".length())
		{
			return base.substring(0, lastSlash) + "/sync-push";
		}
		return base + "/sync-push";
	}
}

package com.geiq.plugin;

import java.util.Collections;
import java.util.List;
import lombok.Data;

/**
 * Snapshot of the user's GE IQ state pulled from /api/sync-pull.
 * All collections may be null when deserialized from JSON; use the {@code *OrEmpty}
 * helpers in {@link GeIqPlugin} rather than reading the fields directly.
 */
@Data
public class SyncState
{
	private List<Integer> favorites;
	private List<PortfolioItem> portfolio;
	private List<Investment> investments;
	private String updatedAt;

	public List<Integer> favoritesOrEmpty()
	{
		return favorites != null ? favorites : Collections.emptyList();
	}

	public List<PortfolioItem> portfolioOrEmpty()
	{
		return portfolio != null ? portfolio : Collections.emptyList();
	}

	public List<Investment> investmentsOrEmpty()
	{
		return investments != null ? investments : Collections.emptyList();
	}

	@Data
	public static class PortfolioItem
	{
		private int itemId;
		private Integer buyPrice;
		private Integer sellPrice;
		private Integer soldPrice;
		private Integer quantity;

		public boolean isActive()
		{
			return soldPrice == null;
		}
	}

	@Data
	public static class Investment
	{
		private int itemId;
		private String itemName;
		private int buyPrice;
		private int quantity;
		private Integer targetSellPrice;
		private Integer soldPrice;

		public boolean isActive()
		{
			return soldPrice == null;
		}
	}
}
